-- P/K/S cards (Q 2026-10-16): deck max 25, 5 new type-aware cards per Champion. Needs engine conditions chainHas/prevIs/facingIs/fieldHas + per chainP/K/S.
update public.game_config set value = '25'::jsonb, updated_at = now() where key = 'deck_size';

on conflict (id) do update set name = excluded.name, source = excluded.source, line = excluded.line, type = excluded.type, dmg = excluded.dmg,
  effect = excluded.effect, copies = excluded.copies, sort_order = excluded.sort_order, in_deck = excluded.in_deck, tags = excluded.tags,
  effect_json = excluded.effect_json, cost = excluded.cost, updated_at = now();
